    "java": "private static int endOfQuotedString(String s, int start) {\n    char quote = s.charAt(start);\n    for (int i = start; (i = s.indexOf(quote, i + 1)) >= 0;) {\n      // If there are an even number of preceding backslashes then this is\n      // the end of the string.\n      int slashRunStart = i;\n      while (slashRunStart > start && s.charAt(slashRunStart - 1) == '\\\\') {\n        --slashRunStart;\n      }\n      if (((i - slashRunStart) & 1) == 0) {\n        return i + 1;\n      }\n    }\n    return s.length();\n  }",
    "cangjie": "private static func endOfQuotedString(s: CharArray, start: Int64): Int64 {\n        let quoteChar = s.charAt(start)\n        var i = start\n        while (true) {\n            i = match(s.indexOf(quoteChar, i + 1)) {\n                case Some(val) => val\n                case None => break\n            }\n\n            // If there are an even number of preceding backslashes then this is\n            // the end of the string.\n            var slashRunStart = i\n            while (slashRunStart > start && s.charAt(slashRunStart - 1) == '\\\\') {\n                slashRunStart--\n            }\n            if (((i - slashRunStart) & 1) == 0) {\n                return i + 1\n            }\n        }\n\n        return s.size()\n    }",
