    "java": "private State requireValueState(int pos, State state, boolean canBeKey)\n    throws UnbracketedComma {\n    switch (state) {\n      case START_MAP: case BEFORE_KEY:\n        if (canBeKey) {\n          return State.AFTER_KEY;\n        } else {\n          insert(pos, \"\\\"\\\":\");\n          return State.AFTER_VALUE;\n        }\n      case AFTER_KEY:\n        insert(pos, ':');\n        return State.AFTER_VALUE;\n      case BEFORE_VALUE:\n        return State.AFTER_VALUE;\n      case AFTER_VALUE:\n        if (canBeKey) {\n          insert(pos, ',');\n          return State.AFTER_KEY;\n        } else {\n          insert(pos, \",\\\"\\\":\");\n          return State.AFTER_VALUE;\n        }\n      case START_ARRAY: case BEFORE_ELEMENT:\n        return State.AFTER_ELEMENT;\n      case AFTER_ELEMENT:\n        if (bracketDepth == 0) { throw UNBRACKETED_COMMA; }\n        insert(pos, ',');\n        return State.AFTER_ELEMENT;\n    }\n    throw new AssertionError();\n  }",
    "cangjie": "private func requireValueState(pos: Int64, state: State, canBeKey: Bool): State {\n        match(state) {\n            case START_MAP | BEFORE_KEY => \n                if (canBeKey) {\n                    return State.AFTER_KEY\n                } else {\n                    insert(pos, #\"\"\":\"#)\n                    return State.AFTER_VALUE\n                }\n            case AFTER_KEY => \n                insert(pos, ':')\n                return State.AFTER_VALUE\n            case BEFORE_VALUE => \n                return State.AFTER_VALUE\n            case AFTER_VALUE => \n                if (canBeKey) {\n                    insert(pos, ',')\n                    return State.AFTER_KEY\n                } else {\n                    insert(pos, #\",\"\":\"#)\n                    return State.AFTER_VALUE\n                }\n            case START_ARRAY | BEFORE_ELEMENT => \n                return State.AFTER_ELEMENT\n            case AFTER_ELEMENT => \n                if (bracketDepth == 0) {\n                    throw UNBRACKETED_COMMA\n                }\n                insert(pos, ',')\n                return State.AFTER_ELEMENT\n        }\n    }",
