    "java": "private static int unescapedCharRev(String s, int rightIncl) {\n    if (rightIncl < 0) {\n      return 0;\n    }\n    // \\?\n    // \\01\n    // \\012\n    // \\x00\n    // \\u0000\n    for (int i = 1; i < 6; ++i) {\n      int left = rightIncl - i;\n      if (left < 0) { break; }\n      if (s.charAt(left) == '\\\\') {\n        // If there are an odd number of '\\\\' then decode.\n        int n = 1;\n        while (left - n >= 0 && s.charAt(left - n) == '\\\\') {\n          ++n;\n        }\n        if ((n & 1) == 1) {\n          int unescaped = unescapedChar(s, left);\n          if ((unescaped >>> 16) - 1 == i) {\n            return unescaped;\n          }\n        }\n        break;\n      }\n    }\n    return 0x10000 | s.charAt(rightIncl);\n  }",
