    "java": "public ByteBuffer filterWithoutEnglishLetters(final byte[] buf, int offset, int length) {\n        ByteBuffer out = ByteBuffer.allocate(length);\n        \n        boolean meetMSB = false;\n        byte c;\n\n        int prevPtr = offset;\n        int curPtr = offset;\n        int maxPtr = offset + length;\n        \n        for (; curPtr<maxPtr; ++curPtr) {\n            c = buf[curPtr];\n            if (!isAscii(c)) {\n                meetMSB = true;\n            } else if (isAsciiSymbol(c)) {\n                // current char is a symbol, most likely a punctuation.\n                // we treat it as segment delimiter\n                if (meetMSB && curPtr > prevPtr) {\n                    // this segment contains more than single symbol,\n                    // and it has upper ASCII, we need to keep it\n                    out.put(buf, prevPtr, (curPtr-prevPtr));\n                    out.put((byte)ASCII_SP);\n                    prevPtr = curPtr + 1;\n                    meetMSB = false;\n                } else {\n                    // ignore current segment.\n                    // (either because it is just a symbol or just an English word)\n                    prevPtr = curPtr + 1;\n                }\n            }\n        }\n        \n        if (meetMSB && curPtr > prevPtr) {\n            out.put(buf, prevPtr, (curPtr-prevPtr));\n        }\n        \n        return out;\n    }",
    "cangjie": "public func filterWithoutEnglishLetters(buf: Array<Byte>, offset: Int32, length: Int32): ByteBuffer {\n        if (buf.size == 0) {\n            throw ChardetException(\"this buf is empty\")\n        }\n        var out: ByteBuffer = ByteBuffer.allocate(Int64(length))\n\n        var meetMSB: Bool = false\n        var c: Byte = 0\n\n        var prevPtr: Int32 = offset\n        var curPtr: Int32 = offset\n        var maxPtr: Int32 = offset + length\n        if (maxPtr <= 0) {\n            throw ChardetException(\"this length is null\")\n        }\n        for (_ in curPtr..maxPtr) {\n            c = buf[Int64(curPtr)]\n            if (!isAscii(c)) {\n                meetMSB = true\n            } else if (isAsciiSymbol(c)) {\n\n                if (meetMSB && curPtr > prevPtr) {\n                    // this segment contains more than single symbol,\n                    // and it has upper ASCII, we need to keep it\n                    out.put(buf, Int64(prevPtr), Int64(curPtr-prevPtr))\n                    out.put(UInt8(ASCII_SP))\n                    prevPtr = curPtr + 1\n                    meetMSB = false\n                } else {\n                    prevPtr = curPtr + 1\n                }\n\n            }\n            curPtr++\n        }\n\n        if (meetMSB && curPtr > prevPtr) {\n            out.put(buf, Int64(prevPtr), Int64(curPtr-prevPtr))\n        }\n        return out\n    }",
