    "java": "public UnicodeBOMInputStream(final InputStream inputStream,\n   boolean skipIfFound) throws IOException {\n  if (inputStream == null) {\n   throw new NullPointerException(\n     \"invalid input stream: null is not allowed\");\n  }\n  in = new PushbackInputStream(inputStream, 4);\n\n  final byte bom[] = new byte[4];\n  final int read = in.read(bom);\n\n  switch (read) {\n  case 4:\n   if ((bom[0] == (byte) 0xFF) && (bom[1] == (byte) 0xFE)\n     && (bom[2] == (byte) 0x00) && (bom[3] == (byte) 0x00)) {\n    this.bom = BOM.UTF_32_LE;\n    break;\n   } else if ((bom[0] == (byte) 0x00) && (bom[1] == (byte) 0x00)\n     && (bom[2] == (byte) 0xFE) && (bom[3] == (byte) 0xFF)) {\n    this.bom = BOM.UTF_32_BE;\n    break;\n   }\n\n  case 3:\n   if ((bom[0] == (byte) 0xEF) && (bom[1] == (byte) 0xBB)\n     && (bom[2] == (byte) 0xBF)) {\n    this.bom = BOM.UTF_8;\n    break;\n   }\n\n  case 2:\n   if ((bom[0] == (byte) 0xFF) && (bom[1] == (byte) 0xFE)) {\n    this.bom = BOM.UTF_16_LE;\n    break;\n   } else if ((bom[0] == (byte) 0xFE) && (bom[1] == (byte) 0xFF)) {\n    this.bom = BOM.UTF_16_BE;\n    break;\n   }\n\n  default:\n   this.bom = BOM.NONE;\n   break;\n  }\n\n  if (read > 0) {\n   in.unread(bom, 0, read);\n  }\n  if (skipIfFound) {\n   this.skipBOM();\n  }\n\n }",
    "cangjie": "public init(inputStream: InputStream, skipIfFound: Bool) {\n        \n        if ((inputStream as Seekable).getOrThrow().length == 0) {\n   throw ChardetException(\"invalid input stream: null is not allowed\")\n  }\n        ins = inputStream\n        var boms: Array<Byte> = Array<Byte>(4, item: 0)\n\n        var read = ins.read(boms)\n\n        match (read) {\n      case 4 =>\n       if (checkval(boms)) {\n        this.bom = BOM.UTF_32_LE\n                    \n       } else if (checkval2(boms)) {\n        this.bom = BOM.UTF_32_BE\n                    \n       }\n            case 3 =>\n       if (checkval3(boms)){\n        this.bom = BOM.UTF_8 \n                    \n       }\n            case 2 =>\n       if ((boms[0] == 0xFF) && (boms[1] == 0xFE)) {\n        this.bom = BOM.UTF_16_LE\n                    \n       } else if ((boms[0] == 0xFE) && (boms[1] == 0xFF)) {\n        this.bom = BOM.UTF_16_BE\n                    \n       }\n            case _ =>\n                this.bom = BOM.NONE    \n        }\n\n        if (bom.toString().isEmpty()) {\n      this.bom = BOM.NONE\n  }\n\n        if (skipIfFound) {\n   if (!skipped) {\n       var bytesToSkip: Int64 = bom.bytes.size\n                var bytesSkipped: Int64 = -1\n                if (bytesToSkip < (ins as Seekable).getOrThrow().length) {\n                    bytesSkipped = bytesToSkip\n                } else {\n                    bytesSkipped = (ins as Seekable).getOrThrow().length\n                }\n                if (bytesSkipped > 0) {\n                    var skips: Array<Byte> = Array<Byte>(bytesSkipped, item: 0)\n                    ins.read(skips)\n                }\n                var byteskips: Array<Byte> = Array<Byte>(1, item: 0)\n       for (_ in bytesSkipped..bytesToSkip) {\n        ins.read(byteskips)\n       }\n       skipped = true\n      }\n  \n     }\n  \n    }",
