    "java": "private static String detectCharsetFromBOM(final byte[] buf, int offset) {\n  if (buf.length > (offset + 3)) {\n   int b1 = buf[offset] & 0xFF;\n   int b2 = buf[offset+1] & 0xFF;\n   int b3 = buf[offset+2] & 0xFF;\n   int b4 = buf[offset+3] & 0xFF;\n   \n   switch (b1) {\n   case 0xEF:\n       if (b2 == 0xBB && b3 == 0xBF) {\n           return CHARSET_UTF_8;\n       }\n       break;\n   case 0xFE:\n       if (b2 == 0xFF && b3 == 0x00 && b4 == 0x00) {\n           return CHARSET_X_ISO_10646_UCS_4_3412;\n       } else if (b2 == 0xFF) {\n           return CHARSET_UTF_16BE;\n       }\n       break;\n   case 0x00:\n       if (b2 == 0x00 && b3 == 0xFE && b4 == 0xFF) {\n           return CHARSET_UTF_32BE;\n       } else if (b2 == 0x00 && b3 == 0xFF && b4 == 0xFE) {\n           return CHARSET_X_ISO_10646_UCS_4_2143;\n       }\n       break;\n   case 0xFF:\n       if (b2 == 0xFE && b3 == 0x00 && b4 == 0x00) {\n           return CHARSET_UTF_32LE;\n       } else if (b2 == 0xFE) {\n           return CHARSET_UTF_16LE;\n       }\n       break;\n   default: \n    break;\n   } // swich end\n  }\n  return null;\n }",
    "cangjie": "private static func detectCharsetFromBOM(buf: Array<Byte>, offset: Int32): String {\n        if (buf.size > Int64(offset + 3)) {\n   let b1 = buf[Int64(offset)] & 0xFF\n   let b2 = buf[Int64(offset+1)] & 0xFF\n   let b3 = buf[Int64(offset+2)] & 0xFF\n   let b4 = buf[Int64(offset+3)] & 0xFF\n            match (b1) {\n                case 0xEF =>\n                    if (b2 == 0xBB && b3 == 0xBF) {\n               return Constants.CHARSET_UTF_8\n           }\n                \n                case 0xFE =>\n                    if (b2 == 0xFF && b3 == 0x00 && b4 == 0x00) {\n                        return \"CHARSET_X_ISO_10646_UCS_4_3412\"\n           } else if (b2 == 0xFF) {\n               return Constants.CHARSET_UTF_16BE\n           }\n                case 0x00 =>\n                    if (b2 == 0x00 && b3 == 0xFE && b4 == 0xFF) {\n                        return \"CHARSET_UTF_32BE\"\n           } else if (b2 == 0x00 && b3 == 0xFF && b4 == 0xFE) {\n                        return \"CHARSET_X_ISO_10646_UCS_4_2143\"\n           } \n                case 0xFF => \n                    if (b2 == 0xFE && b3 == 0x00 && b4 == 0x00) {\n                        return \"CHARSET_UTF_32LE\"\n           } else if (b2 == 0xFE) {\n               return Constants.CHARSET_UTF_16LE\n           }   \n                case _ =>\n                    ()\n            }\n     \n        }\n        return \"\"  \n    }",
