    "id": "commonsText_FuzzyScore_fuzzyScore",
    "title": "commonsText / FuzzyScore_fuzzyScore",
    "family": "commonsText",
    "java": "public Integer fuzzyScore(final CharSequence term, final CharSequence query) {\n        if (term == null || query == null) {\n            throw new IllegalArgumentException(\"CharSequences must not be null\");\n        }\n\n        // fuzzy logic is case insensitive. We normalize the Strings to lower\n        // case right from the start. Turning characters to lower case\n        // via Character.toLowerCase(char) is unfortunately insufficient\n        // as it does not accept a locale.\n        final String termLowerCase = term.toString().toLowerCase(locale);\n        final String queryLowerCase = query.toString().toLowerCase(locale);\n\n        // the resulting score\n        int score = 0;\n\n        // the position in the term which will be scanned next for potential\n        // query character matches\n        int termIndex = 0;\n\n        // index of the previously matched character in the term\n        int previousMatchingCharacterIndex = Integer.MIN_VALUE;\n\n        for (int queryIndex = 0; queryIndex < queryLowerCase.length(); queryIndex++) {\n            final char queryChar = queryLowerCase.charAt(queryIndex);\n\n            boolean termCharacterMatchFound = false;\n            for (; termIndex < termLowerCase.length()\n                    && !termCharacterMatchFound; termIndex++) {\n                final char termChar = termLowerCase.charAt(termIndex);\n\n                if (queryChar == termChar) {\n                    // simple character matches result in one point\n                    score++;\n\n                    // subsequent character matches further improve\n                    // the score.\n                    if (previousMatchingCharacterIndex + 1 == termIndex) {\n                        score += 2;\n                    }\n\n                    previousMatchingCharacterIndex = termIndex;\n\n                    // we can leave the nested loop. Every character in the\n                    // query can match at most one character in the term.\n                    termCharacterMatchFound = true;\n                }\n            }\n        }\n\n        return score;\n    }",
    "cangjie": "private func fuzzyScore(term: String, query: String, t:Int32): Int32{\n        var score: Int32 = 0\n        var previousMatchingCharaterIndex: Int64 = -2147483647\n        var lowQuery :String = \"\"; \n        var lowTerm: String = \"\";\n        if (t == 0){\n            lowQuery = query.toAsciiLower()\n            lowTerm = term.toAsciiLower()\n        } else{\n            lowQuery = query.toLower()\n            lowTerm = term.toLower()\n        }\n        var queryIndex:Int64 = 0\n        var termIndex: Int64 = 0\n        while(queryIndex < lowQuery.size){\n            let c = lowQuery.get(queryIndex)\n            while(termIndex<lowTerm.size){\n                 let t = lowTerm.get(termIndex)\n                 if (c == t){\n                    score++\n                    if (previousMatchingCharaterIndex+1==termIndex){\n                        score +=2\n                    }\n                    previousMatchingCharaterIndex = termIndex\n                    termIndex++\n                    break\n                }\n                termIndex++\n            }\n            queryIndex++;\n        }\n        return score\n    }",
