    "family": "commonsText",
    "java": "public LookupTranslator(final Map<CharSequence, CharSequence> lookupMap) {\n        if (lookupMap == null) {\n            throw new InvalidParameterException(\"lookupMap cannot be null\");\n        }\n        this.lookupMap = new HashMap<>();\n        this.prefixSet = new BitSet();\n        int currentShortest = Integer.MAX_VALUE;\n        int currentLongest = 0;\n\n        for (final Map.Entry<CharSequence, CharSequence> pair : lookupMap.entrySet()) {\n            this.lookupMap.put(pair.getKey().toString(), pair.getValue().toString());\n            this.prefixSet.set(pair.getKey().charAt(0));\n            final int sz = pair.getKey().length();\n            if (sz < currentShortest) {\n                currentShortest = sz;\n            }\n            if (sz > currentLongest) {\n                currentLongest = sz;\n            }\n        }\n        this.shortest = currentShortest;\n        this.longest = currentLongest;\n    }",
    "cangjie": "public init(lookupMap: Map<String, String>) {\n        this.lookupMap = lookupMap\n        this.prefixSet = HashSet<Char>()\n        var currentShortest = 0x10FFFF;\n        var currentLongest = 0;\n\n        for ((key, value) in lookupMap) {\n            if(key.size < 1) {\n                continue;\n            }\n            this.prefixSet.put(key.get(0) ?? Char(0x10FFFF));\n            this.lookupMap.put(key, value);\n            let sz = key.size;\n            if (sz < currentShortest) {\n                currentShortest = sz\n            }\n            if (sz > currentLongest) {\n                currentLongest = sz\n            }\n        }\n        this.shortest = currentShortest\n        this.longest = currentLongest\n    }",
