    "java": "@Override\n    public int translate(final CharSequence input, final int index, final Writer writer) throws IOException {\n        // check if translation exists for the input at position index\n        if (prefixSet.get(input.charAt(index))) {\n            int max = longest;\n            if (index + longest > input.length()) {\n                max = input.length() - index;\n            }\n            // implement greedy algorithm by trying maximum match first\n            for (int i = max; i >= shortest; i--) {\n                final CharSequence subSeq = input.subSequence(index, index + i);\n                final String result = lookupMap.get(subSeq.toString());\n\n                if (result != null) {\n                    writer.write(result);\n                    return Character.codePointCount(subSeq, 0, subSeq.length());\n                }\n            }\n        }\n        return 0;\n    }",
    "cangjie": "public override func translate(input: String, index: Int64, writer: Writer): Int64 {\n        // check if translation exists for the input at position index\n        if (prefixSet.contains(input.get(index) ?? '\\0')) {\n            var max = longest\n            if (index + longest > input.size) {\n                max = input.size - index\n            }\n\n            // implement greedy algorithm by trying maximum match first\n            var i = max\n            while (i >= shortest) {\n                let subSeq = input.substring(index, i);\n                if (lookupMap.contains(subSeq)) {\n                    writer.write(lookupMap.get(subSeq) ?? \"\");\n                    return subSeq.size;\n                }\n                i--\n            }\n        }\n\n        return 0;\n    }",
